import{_ as r,o,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Learn Ceph — For Fun, For Real, For Free! - Florian Haas, City Network","description":"","frontmatter":{"title":"Learn Ceph — For Fun, For Real, For Free! - Florian Haas, City Network","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","在线学习","City Cloud Academy","Open EDX"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Learn_Ceph_For_Fun_For_Real_For_Free_-_Florian_Haas_City_Network.md","filePath":"posts/2019/Learn_Ceph_For_Fun_For_Real_For_Free_-_Florian_Haas_City_Network.md","lastUpdated":1780459816000}'),l={name:"posts/2019/Learn_Ceph_For_Fun_For_Real_For_Free_-_Florian_Haas_City_Network.md"};function i(n,e,_,s,p,C){return o(),t("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 云学院课程更新及用户反馈征集</p><p><strong>会议时间</strong>： [具体时间]</p><p><strong>参会人员</strong>： [参会人员名单]</p><p><strong>会议内容</strong>：</p><p><strong>一、会议背景</strong></p><p>Florian Haas 主讲，介绍了 Ceph 云学院（City Cloud Academy）的更新情况，特别是针对 Ceph 分布式存储基础课程（CC 212）的改进和新增内容。</p><p><strong>二、讨论的主要议题</strong></p><ol><li><strong>传统培训模式局限性</strong>： 面对面培训成本高、效率低、难以规模化。</li><li><strong>在线学习不足</strong>： 缺乏互动性和实践性，不利于学习者掌握复杂技术。</li><li><strong>Ceph 云学院优势</strong>： 基于 Open EDX 平台，提供沉浸式、互动性强的实验室环境，允许学习者交流，快速创新和开放。</li><li><strong>课程更新</strong>： <ul><li>更新至 Nautilus 版本</li><li>使用 CephFS 卷而非 Ceph Disk</li><li>涵盖更多 Ceph 技术细节，如 fuse、内核文件系统驱动等</li><li>提供实用的仪表盘操作内容</li><li>涵盖 Eurasia 代码库和配置文件</li><li>更新至最新版本</li></ul></li></ol><p><strong>三、决定的事项</strong></p><ol><li>Ceph 云学院将继续免费提供 CC 212 课程，每月开放 20 个免费名额。</li><li>欢迎用户反馈课程内容，以便持续改进课程质量。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>Ceph 云学院团队将根据用户反馈，不断完善课程内容。</li><li>Ceph 云学院将积极推广课程，扩大用户群体。</li></ol><p><strong>五、其他事项</strong></p><ol><li>用户可以通过访问 City Cloud Academy 网站查看课程详情。</li><li>用户可以通过 Twitter 关注 Ceph 云学院，获取最新课程信息。</li></ol><p><strong>会议总结</strong>：</p><p>本次会议介绍了 Ceph 云学院的课程更新情况，并强调了用户反馈对课程改进的重要性。Ceph 云学院将继续致力于提供高质量、实用的 Ceph 技术培训，帮助用户更好地掌握 Ceph 技术。</p>',17)])])}const h=r(l,[["render",i]]);export{g as __pageData,h as default};
